<#
.SYNOPSIS
Installs SSE stall recovery into an existing OMP compatibility shim.
.EXAMPLE
powershell -NoProfile -ExecutionPolicy Bypass -File .\bin\apply-sse-watchdog.ps1 -DryRun
.EXAMPLE
.\bin\apply-sse-watchdog.ps1 -ShimDirectory 'C:\tools\codex-chatgpt-web-omp-shim'
#>
[CmdletBinding()]
param(
    [string]$ShimDirectory,
    [switch]$DryRun
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$utf8 = New-Object System.Text.UTF8Encoding($false)

# BEGIN EMBEDDED WATCHDOG
# Generated by bin/build-powershell.py; no companion files required.
$manifestJson = @'
{
  "replacements": [
    {
      "old": "import { isAbsolute } from \"node:path\";",
      "new": "import { isAbsolute, join } from \"node:path\";\nimport { homedir } from \"node:os\";\nimport { guardResponseStream } from \"./sse-watchdog\";"
    },
    {
      "old": "const threadTails =",
      "new": "async function interruptNativeTurn(threadId: string | undefined, turnId: string | undefined) {\n  if (!threadId || !turnId) return;\n  const configPath = join(process.env.CODEX_CHATGPT_WEB_HOME || join(homedir(), \".codex-chatgpt-web\"), \"config.json\");\n  const config = await Bun.file(configPath).json();\n  if (typeof config.controlToken !== \"string\") throw new Error(\"Missing local Web control token\");\n  const result = await fetch(new URL(\"/admin/interrupt-turn\", upstreamOrigin), {\n    method: \"POST\",\n    headers: { authorization: `Bearer ${config.controlToken}`, \"content-type\": \"application/json\" },\n    body: JSON.stringify({ threadId, turnId }),\n    signal: AbortSignal.timeout(5000),\n  });\n  if (!result.ok) throw new Error(`Native turn interruption HTTP ${result.status}`);\n  console.log(\"OMP interrupted native Web turn\", { thread: threadId.slice(0, 8), turn: turnId.slice(0, 8), ...await result.json() });\n}\n\nconst threadTails ="
    },
    {
      "old": "let threadId = threadIdFromMetadata(headerTurnMetadata);",
      "new": "let threadId = threadIdFromMetadata(headerTurnMetadata);\n    let turnId: string | undefined;"
    },
    {
      "old": "const metadata = JSON.parse(rewrittenTurnMetadata!);",
      "new": "const metadata = JSON.parse(rewrittenTurnMetadata!);\n            if (typeof metadata.turn_id === \"string\") turnId = metadata.turn_id;"
    },
    {
      "old": "const responseBody = isOmpStream ? translateResponseStream(upstream.body!) : upstream.body;",
      "new": "const guardedBody = isOmpStream && threadId && turnId ? guardResponseStream(upstream.body!, {\n      onStall: () => interruptNativeTurn(threadId, turnId),\n      onCancel: () => interruptNativeTurn(threadId, turnId),\n    }) : upstream.body;\n    const responseBody = isOmpStream ? translateResponseStream(guardedBody!) : guardedBody;"
    }
  ],
  "installedMarkers": [
    "import { guardResponseStream } from \"./sse-watchdog\";",
    "const guardedBody = isOmpStream && threadId && turnId ? guardResponseStream(upstream.body!, {\n      onStall: () => interruptNativeTurn(threadId, turnId),\n      onCancel: () => interruptNativeTurn(threadId, turnId),\n    }) : upstream.body;\n    const responseBody = isOmpStream ? translateResponseStream(guardedBody!) : guardedBody;",
    "async function interruptNativeTurn(threadId: string | undefined, turnId: string | undefined) {\n  if (!threadId || !turnId) return;\n  const configPath = join(process.env.CODEX_CHATGPT_WEB_HOME || join(homedir(), \".codex-chatgpt-web\"), \"config.json\");\n  const config = await Bun.file(configPath).json();\n  if (typeof config.controlToken !== \"string\") throw new Error(\"Missing local Web control token\");\n  const result = await fetch(new URL(\"/admin/interrupt-turn\", upstreamOrigin), {\n    method: \"POST\",\n    headers: { authorization: `Bearer ${config.controlToken}`, \"content-type\": \"application/json\" },\n    body: JSON.stringify({ threadId, turnId }),\n    signal: AbortSignal.timeout(5000),\n  });\n  if (!result.ok) throw new Error(`Native turn interruption HTTP ${result.status}`);\n  console.log(\"OMP interrupted native Web turn\", { thread: threadId.slice(0, 8), turn: turnId.slice(0, 8), ...await result.json() });\n}",
    "let turnId: string | undefined;",
    "if (typeof metadata.turn_id === \"string\") turnId = metadata.turn_id;"
  ]
}
'@
$moduleText = @'
// Transport heartbeats prove the socket is alive, not that a model turn progresses.
// Keep the budget below OMP's 300s semantic watchdog so we can retire the Web turn.
export function guardResponseStream(source: ReadableStream<Uint8Array>, options: {
  timeoutMs?: number;
  onStall: () => Promise<void>;
  onCancel: () => Promise<void>;
}): ReadableStream<Uint8Array> {
  const timeoutMs = options.timeoutMs ?? 240_000;
  const reader = source.getReader();
  const decoder = new TextDecoder();
  const encoder = new TextEncoder();
  let pending = "";
  let timer: ReturnType<typeof setTimeout> | undefined;
  let closed = false;
  let terminal = false;
  let responseId = "";
  let sequence = 0;
  let cleanup: Promise<void> | undefined;
  let observe: (chunk: Uint8Array) => void = () => {};
  const clear = () => { clearTimeout(timer); timer = undefined; };
  const retire = (callback: () => Promise<void>) => cleanup ??= callback().catch(error => {
    console.warn("OMP Web turn cleanup failed", error instanceof Error ? error.message : String(error));
  });

  return new ReadableStream<Uint8Array>({
    start(controller) {
      const arm = () => {
        clear();
        if (closed || terminal) return;
        timer = setTimeout(async () => {
          if (closed || terminal) return;
          closed = true;
          console.warn("OMP Web semantic timeout", { timeoutMs, responseId });
          // Cancel this native turn before the client can retry into the old broker.
          await retire(options.onStall);
          const failure = { type: "response.failed", sequence_number: sequence++, response: {
            id: responseId || "resp_omp_stalled", status: "failed", output: [],
            error: { type: "server_error", code: "chatgpt_web_semantic_timeout",
              message: "ChatGPT Web made no semantic progress for the configured timeout; the stuck Web turn was interrupted. Send a new continue message to resume." },
          } };
          try {
            controller.enqueue(encoder.encode(`event: response.failed\ndata: ${JSON.stringify(failure)}\n\ndata: [DONE]\n\n`));
            controller.close();
          } catch { /* downstream may already be gone */ }
          void reader.cancel("ChatGPT Web semantic timeout").catch(() => {});
        }, timeoutMs);
      };
      // Only complete Responses events count. Comments and response.heartbeat do not.
      observe = (chunk: Uint8Array) => {
        pending += decoder.decode(chunk, { stream: true });
        let end: number;
        while ((end = pending.indexOf("\n")) >= 0) {
          const line = pending.slice(0, end).trimEnd();
          pending = pending.slice(end + 1);
          if (!line.startsWith("data:")) continue;
          try {
            const event = JSON.parse(line.slice(5).trim());
            if (typeof event.sequence_number === "number") sequence = Math.max(sequence, event.sequence_number + 1);
            if (typeof event.response?.id === "string") responseId = event.response.id;
            if (["response.completed", "response.incomplete", "response.failed", "error"].includes(event.type)) {
              terminal = true;
              clear();
            } else if (event.type === "response.created" || /^response\.(output_item|content_part|reasoning_summary_part)\.(added|done)$/.test(event.type)
              || /^response\.(output_text|reasoning_text|reasoning_summary_text|refusal|function_call_arguments|custom_tool_call_input)\.(delta|done)$/.test(event.type)) {
              arm();
            }
          } catch { /* comments, [DONE], or invalid JSON: leave original bytes intact */ }
        }
      };
      arm();
    },
    async pull(controller) {
      try {
        const { done, value } = await reader.read();
        if (closed) return;
        if (done) {
          closed = true;
          clear();
          controller.close();
        } else {
          observe(value);
          controller.enqueue(value);
        }
      } catch (error) {
        if (closed) return;
        closed = true;
        clear();
        if (!terminal) await retire(options.onCancel);
        controller.error(error);
      }
    },
    async cancel(reason) {
      if (closed) return;
      closed = true;
      clear();
      if (!terminal) await retire(options.onCancel);
      await reader.cancel(reason).catch(() => {});
    },
  });
}
'@
$moduleText += "`n"
# END EMBEDDED WATCHDOG

function Replace-ExactlyOnce([string]$Text, [string]$Old, [string]$New) {
    $count = [regex]::Matches($Text, [regex]::Escape($Old)).Count
    if ($count -ne 1) {
        throw "Unsupported shim layout: expected one match, got $count. No files changed."
    }
    return $Text.Replace($Old, $New)
}

try {
    if (-not $ShimDirectory) {
        $userDirectory = [Environment]::GetFolderPath('UserProfile')
        $candidates = @((Join-Path $userDirectory '.local/share/codex-chatgpt-web-omp-shim'))
        foreach ($envName in @('LOCALAPPDATA', 'APPDATA')) {
            $baseDirectory = [Environment]::GetEnvironmentVariable($envName)
            if ($baseDirectory) {
                $candidates += Join-Path $baseDirectory 'codex-chatgpt-web-omp-shim'
            }
        }
        $foundShims = @($candidates | Select-Object -Unique | Where-Object {
            [IO.File]::Exists((Join-Path $_ 'server.ts'))
        })
        if ($foundShims.Count -eq 0) {
            throw 'Existing compatibility shim not found. Supply -ShimDirectory pointing to the folder containing server.ts.'
        }
        if ($foundShims.Count -ne 1) {
            throw 'Multiple compatibility shims found. Choose the running shim with -ShimDirectory.'
        }
        $ShimDirectory = $foundShims[0]
    }

    $serverPath = [IO.Path]::GetFullPath((Join-Path $ShimDirectory 'server.ts'))
    if (-not [IO.File]::Exists($serverPath)) {
        throw "Existing compatibility shim required: $serverPath"
    }
    $manifest = $manifestJson | ConvertFrom-Json
    $original = [IO.File]::ReadAllText($serverPath, $utf8)
    $updated = $original.Replace("`r`n", "`n")

    if ($updated.Contains([string]$manifest.installedMarkers[0])) {
        foreach ($marker in $manifest.installedMarkers) {
            if (-not $updated.Contains([string]$marker)) {
                throw 'Existing watchdog integration differs from the tested layout. No files changed.'
            }
        }
    } else {
        foreach ($replacement in $manifest.replacements) {
            $updated = Replace-ExactlyOnce $updated $replacement.old $replacement.new
        }
    }
    if ($original.Contains("`r`n")) {
        $updated = $updated.Replace("`n", "`r`n")
    }

    $modulePath = Join-Path (Split-Path -Parent $serverPath) 'sse-watchdog.ts'
    $changes = @()
    if ($updated -cne $original) {
        $changes += [pscustomobject]@{ Path = $serverPath; Text = $updated }
    }
    if (-not [IO.File]::Exists($modulePath) -or [IO.File]::ReadAllText($modulePath, $utf8) -cne $moduleText) {
        $changes += [pscustomobject]@{ Path = $modulePath; Text = $moduleText }
    }
    if ($changes.Count -eq 0) {
        Write-Output 'SSE watchdog already installed (240 seconds without semantic progress).'
        exit 0
    }
    if ($DryRun) {
        foreach ($change in $changes) { Write-Output "Would install: $($change.Path)" }
        exit 0
    }

    $stamp = Get-Date -Format 'yyyyMMdd-HHmmss-fffffff'
    $snapshots = @()
    # Validate/read every source and destination before any mutation.
    foreach ($change in $changes) {
        $exists = [IO.File]::Exists($change.Path)
        $bytes = $null
        if ($exists) { $bytes = [IO.File]::ReadAllBytes($change.Path) }
        $snapshots += [pscustomobject]@{ Path = $change.Path; Existed = $exists; Bytes = $bytes }
    }
    try {
        foreach ($change in $changes) {
            if ([IO.File]::Exists($change.Path)) {
                $backupPath = "$($change.Path).pre-sse-watchdog-$stamp.bak"
                [IO.File]::Copy($change.Path, $backupPath, $false)
                Write-Output "Backup: $backupPath"
            }
            [IO.File]::WriteAllText($change.Path, $change.Text, $utf8)
        }
    } catch {
        $installError = $_
        foreach ($snapshot in $snapshots) {
            if ($snapshot.Existed) {
                [IO.File]::WriteAllBytes($snapshot.Path, $snapshot.Bytes)
            } elseif ([IO.File]::Exists($snapshot.Path)) {
                [IO.File]::Delete($snapshot.Path)
            }
        }
        throw $installError
    }
    Write-Output 'Installed. Once active turns finish, restart the process/service running this shim.'
    Write-Output 'Then send a new continue message in OMP. No administrator access or Python is needed.'
} catch {
    [Console]::Error.WriteLine("ERROR: $($_.Exception.Message)")
    exit 1
}
